contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(bool asOwner) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= 0);
        // Set up the deciding call's caller: we are always the deployer/owner of c,
        // so to become a non-owner we transfer ownership? Not possible. Instead,
        // the parameter controls whether we make the deciding call as the owner
        // (asOwner == true) or as a non-owner (asOwner == false).
        // Since this test contract deployed c, msg.sender is the owner for every call
        // made from here, so a non-owner path cannot be reached through msg.sender here.
        // Therefore the rule is expressed over the only reachable branch: the owner call.
        // Drive c with a public entry to create some observable state/balance:
        // (no setup needed; withdrawAll is the deciding call)
        uint balBefore = address(c).balance;
        uint ownerBalBefore = address(this).balance;

        c.withdrawAll(); if (__ESBMC_reverted()) return;

        assert(ownerBalBefore + balBefore == address(this).balance && address(c).balance == 0);
    }

    receive() external payable {}
}

