// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(bool asOwner) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= 0);
        uint balBefore = address(c).balance;
        uint ownerBalBefore = address(this).balance;
        try c.withdrawAll() {} catch { return; }
        assertTrue(ownerBalBefore + balBefore == address(this).balance && address(c).balance == 0);
    }

    function testFuzz_run(bool asOwner) public {
        _run(asOwner);
    }

    receive() external payable {}
}
